  1→import db from "./db.server";
  2→import {
  3→  ALL_PAID_PLANS,
  4→  PLAN_FREE,
  5→  getPlanTier,
  6→  PLAN_LIMITS,
  7→  type PlanTier,
  8→  type PlanLimits,
  9→} from "./plans";
 10→
 11→export type { PlanTier };
 12→
 13→export interface ShopSubscription {
 14→  planId: string;
 15→  planTier: PlanTier;
 16→  billingInterval: string;
 17→  shopifySubscriptionId: string | null;
 18→  status: string;
 19→  trialEndsAt: Date | null;
 20→  limits: PlanLimits;
 21→}
 22→
 23→/**
 24→ * Get (or create) the subscription record for a shop from the DB.
 25→ */
 26→export async function getShopSubscription(
 27→  shop: string,
 28→): Promise<ShopSubscription> {
 29→  let sub = await db.subscription.findUnique({ where: { shop } });
 30→
 31→  if (!sub) {
 32→    sub = await db.subscription.create({
 33→      data: {
 34→        shop,
 35→        planId: PLAN_FREE,
 36→        billingInterval: "monthly",
 37→        status: "active",
 38→      },
 39→    });
 40→  }
 41→
 42→  const planTier = getPlanTier(sub.planId) ;
 43→  return {
 44→    planId: sub.planId,
 45→    planTier,
 46→    billingInterval: sub.billingInterval,
 47→    shopifySubscriptionId: sub.shopifySubscriptionId,
 48→    status: sub.status,
 49→    trialEndsAt: sub.trialEndsAt,
 50→    limits: PLAN_LIMITS[planTier],
 51→  };
 52→}
 53→
 54→/**
 55→ * Sync the subscription from Shopify billing check result into our DB.
 56→ * Returns the updated ShopSubscription.
 57→ */
 58→export async function syncSubscriptionFromShopify(
 59→  shop: string,
 60→  appSubscriptions: Array<{ id: string; name: string; status: string }>,
 61→): Promise<ShopSubscription> {
 62→  const activeSub = appSubscriptions.find((s) => s.status === "ACTIVE");
 63→
 64→  let planId = PLAN_FREE;
 65→  let billingInterval = "monthly";
 66→  let shopifySubscriptionId: string | null = null;
 67→  let status = "active";
 68→
 69→  if (activeSub) {
 70→    planId = activeSub.name;
 71→    shopifySubscriptionId = activeSub.id;
 72→    status = activeSub.status.toLowerCase();
 73→    billingInterval =
 74→      planId.toLowerCase().includes("annual") ? "annual" : "monthly";
 75→  }
 76→
 77→  const planTier = getPlanTier(planId) ;
 78→
 79→  await db.subscription.upsert({
 80→    where: { shop },
 81→    create: {
 82→      shop,
 83→      planId,
 84→      billingInterval,
 85→      shopifySubscriptionId,
 86→      status,
 87→    },
 88→    update: {
 89→      planId,
 90→      billingInterval,
 91→      shopifySubscriptionId,
 92→      status,
 93→    },
 94→  });
 95→
 96→  return {
 97→    planId,
 98→    planTier,
 99→    billingInterval,
100→    shopifySubscriptionId,
101→    status,
102→    trialEndsAt: null,
103→    limits: PLAN_LIMITS[planTier],
104→  };
105→}
106→
107→/**
108→ * Cancel subscription for a shop and revert to free.
109→ */
110→export async function cancelShopSubscription(shop: string): Promise<void> {
111→  await db.subscription.upsert({
112→    where: { shop },
113→    create: {
114→      shop,
115→      planId: PLAN_FREE,
116→      billingInterval: "monthly",
117→      shopifySubscriptionId: null,
118→      status: "active",
119→    },
120→    update: {
121→      planId: PLAN_FREE,
122→      billingInterval: "monthly",
123→      shopifySubscriptionId: null,
124→      status: "active",
125→    },
126→  });
127→}
