  1→/**
  2→ * Public API endpoint — joins a customer to the waitlist from the storefront widget.
  3→ *
  4→ * Called from the theme app extension block when a zip code check fails and
  5→ * the merchant has enabled the waitlist feature.
  6→ *
  7→ * POST /api/waitlist
  8→ * Body: { shop: string, zip: string, email: string }
  9→ *
 10→ * Response:
 11→ *   200 { success: true, message: "..." }
 12→ *   400 { error: "..." }
 13→ *   500 { error: "..." }
 14→ */
 15→import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→import { getShopSubscription } from "../billing.server";
 18→import { normalizeZipCode } from "../utils/zip";
 19→
 20→const CORS_HEADERS = {
 21→  "Access-Control-Allow-Origin": "*",
 22→  "Access-Control-Allow-Methods": "POST, OPTIONS",
 23→  "Access-Control-Allow-Headers": "Content-Type",
 24→  "Content-Type": "application/json",
 25→};
 26→
 27→// Handle CORS preflight
 28→export const loader = async ({ request }: LoaderFunctionArgs) => {
 29→  if (request.method === "OPTIONS") {
 30→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 31→  }
 32→  return new Response(JSON.stringify({ error: "Method not allowed" }), {
 33→    status: 405,
 34→    headers: CORS_HEADERS,
 35→  });
 36→};
 37→
 38→export const action = async ({ request }: ActionFunctionArgs) => {
 39→  if (request.method === "OPTIONS") {
 40→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 41→  }
 42→
 43→  if (request.method !== "POST") {
 44→    return new Response(JSON.stringify({ error: "Method not allowed" }), {
 45→      status: 405,
 46→      headers: CORS_HEADERS,
 47→    });
 48→  }
 49→
 50→  let shop: string | null = null;
 51→  let zip: string | null = null;
 52→  let email: string | null = null;
 53→  let name: string | null = null;
 54→
 55→  try {
 56→    const body = await request.json();
 57→    shop = body?.shop ?? null;
 58→    zip = body?.zip ?? null;
 59→    email = body?.email ?? null;
 60→    name = body?.name ?? null;
 61→  } catch {
 62→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
 63→      status: 400,
 64→      headers: CORS_HEADERS,
 65→    });
 66→  }
 67→
 68→  if (!shop || !zip || !email) {
 69→    return new Response(
 70→      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
 71→      { status: 400, headers: CORS_HEADERS },
 72→    );
 73→  }
 74→
 75→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 76→  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
 77→    return new Response(
 78→      JSON.stringify({ error: "Invalid shop parameter" }),
 79→      { status: 400, headers: CORS_HEADERS },
 80→    );
 81→  }
 82→
 83→  // Enforce input length limits to prevent abuse
 84→  if (zip.length > 20 || email.length > 254) {
 85→    return new Response(
 86→      JSON.stringify({ error: "Invalid input" }),
 87→      { status: 400, headers: CORS_HEADERS },
 88→    );
 89→  }
 90→
 91→  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
 92→    return new Response(
 93→      JSON.stringify({ error: "Invalid email address" }),
 94→      { status: 400, headers: CORS_HEADERS },
 95→    );
 96→  }
 97→
 98→  // Check if shop's plan allows waitlist
 99→  try {
100→    const subscription = await getShopSubscription(shop);
101→    if (subscription.limits.maxWaitlist === 0) {
102→      return new Response(
103→        JSON.stringify({ error: "Waitlist is not available on this store's plan" }),
104→        { status: 400, headers: CORS_HEADERS },
105→      );
106→    }
107→    // Enforce entry limit for Starter plan
108→    if (subscription.limits.maxWaitlist !== Infinity) {
109→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
110→      if (currentCount >= subscription.limits.maxWaitlist) {
111→        return new Response(
112→          JSON.stringify({ error: "Waitlist is currently full. Please try again later." }),
113→          { status: 400, headers: CORS_HEADERS },
114→        );
115→      }
116→    }
117→  } catch {
118→    // Non-fatal — allow waitlist signup if subscription check fails
119→  }
120→
121→  try {
122→    await db.waitlistEntry.upsert({
123→      where: {
124→        shop_email_zipCode: {
125→          shop,
126→          email,
127→          zipCode: normalizeZipCode(zip),
128→        },
129→      },
130→      create: {
131→        shop,
132→        email,
133→        name: name ? name.trim().substring(0, 100) : null,
134→        zipCode: normalizeZipCode(zip),
135→        status: "waiting",
136→      },
137→      update: {
138→        status: "waiting",
139→      },
140→    });
141→
142→    return new Response(
143→      JSON.stringify({
144→        success: true,
145→        message: "You've been added to the waitlist!",
146→      }),
147→      { status: 200, headers: CORS_HEADERS },
148→    );
149→  } catch {
150→    return new Response(
151→      JSON.stringify({ error: "Failed to join waitlist. Please try again." }),
152→      { status: 500, headers: CORS_HEADERS },
153→    );
154→  }
155→};
