  1→/**
  2→ * Public API endpoint for the storefront zip code widget.
  3→ *
  4→ * Called from the merchant's storefront (Theme App Extension or custom JS)
  5→ * to check whether a zip code is serviceable.
  6→ *
  7→ * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
  8→ *
  9→ * Response:
 10→ *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
 11→ *   200 { allowed: false, message: "..." }
 12→ *   400 { error: "Missing shop or zip parameter" }
 13→ *   404 { allowed: false, message: "Zip code not found", notFound: true }
 14→ */
 15→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→import { normalizeZipCode } from "../utils/zip";
 18→
 19→const CORS_HEADERS = {
 20→  "Access-Control-Allow-Origin": "*",
 21→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
 22→  "Access-Control-Allow-Headers": "Content-Type",
 23→  "Content-Type": "application/json",
 24→};
 25→
 26→// Applied only to successful ZIP check responses (200) to reduce DB load
 27→// for repeated lookups of the same ZIP code from the same storefront visitor.
 28→const SUCCESS_HEADERS = {
 29→  ...CORS_HEADERS,
 30→  "Cache-Control": "public, max-age=60, stale-while-revalidate=120",
 31→};
 32→
 33→const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
 34→
 35→async function handleZipCheck(shop: string | null, zip: string | null) {
 36→  if (!shop || !zip) {
 37→    return new Response(
 38→      JSON.stringify({ error: "Missing shop or zip parameter" }),
 39→      { status: 400, headers: CORS_HEADERS },
 40→    );
 41→  }
 42→
 43→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 44→  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
 45→    return new Response(
 46→      JSON.stringify({ error: "Invalid shop parameter" }),
 47→      { status: 400, headers: CORS_HEADERS },
 48→    );
 49→  }
 50→
 51→  // Enforce input length limits to prevent abuse
 52→  if (zip.length > 20) {
 53→    return new Response(
 54→      JSON.stringify({ error: "Invalid zip code" }),
 55→      { status: 400, headers: CORS_HEADERS },
 56→    );
 57→  }
 58→
 59→  const normalizedZip = normalizeZipCode(zip);
 60→
 61→  try {
 62→  const zipRecord = await db.zipCode.findUnique({
 63→    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
 64→  });
 65→
 66→  // Fetch widget config for custom messages (falls back to defaults)
 67→  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
 68→
 69→  // Fetch shop settings to determine default behavior for unlisted zip codes
 70→  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
 71→  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
 72→
 73→  if (!zipRecord || !zipRecord.isActive) {
 74→    const notFoundMsg =
 75→      widgetConfig?.notFoundMessage ??
 76→      "We currently do not ship to this ZIP code.";
 77→
 78→    // If the zip is simply not in the list (not inactive) and the merchant
 79→    // has set defaultBehavior to "allow", treat it as an allowed zip
 80→    if (!zipRecord && defaultBehavior === "allow") {
 81→      const successMsg =
 82→        widgetConfig?.successMessage ?? "We deliver to your area!";
 83→      return new Response(
 84→        JSON.stringify({
 85→          allowed: true,
 86→          message: successMsg,
 87→          eta: null,
 88→          zone: null,
 89→          codAvailable: null,
 90→          returnPolicy: null,
 91→          showWaitlist: false,
 92→          waitlistCount: 0,
 93→          cutoffTime: null,
 94→          daysOfWeek: null,
 95→        }),
 96→        { status: 200, headers: SUCCESS_HEADERS },
 97→      );
 98→    }
 99→
100→    // Social proof: count how many customers are waiting for this ZIP
101→    let waitlistCount = 0;
102→    try {
103→      waitlistCount = await db.waitlistEntry.count({
104→        where: { shop, zipCode: normalizedZip, status: "waiting" },
105→      });
106→    } catch {
107→      waitlistCount = 0;
108→    }
109→
110→    if (!zipRecord) {
111→      return new Response(
112→        JSON.stringify({
113→          allowed: false,
114→          message: notFoundMsg,
115→          notFound: true,
116→          showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
117→          waitlistCount,
118→        }),
119→        { status: 200, headers: SUCCESS_HEADERS },
120→      );
121→    }
122→
123→    // Inactive zip — treat same as not found regardless of defaultBehavior
124→    return new Response(
125→      JSON.stringify({
126→        allowed: false,
127→        message: notFoundMsg,
128→        notFound: true,
129→        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
130→        waitlistCount,
131→      }),
132→      { status: 200, headers: SUCCESS_HEADERS },
133→    );
134→  }
135→
136→  if (zipRecord.type === "blocked") {
137→    const errorMsg =
138→      zipRecord.message ??
139→      widgetConfig?.errorMessage ??
140→      "Sorry, we don't deliver to this area yet.";
141→
142→    // Social proof: count how many customers are waiting for this ZIP
143→    let waitlistCount = 0;
144→    try {
145→      waitlistCount = await db.waitlistEntry.count({
146→        where: { shop, zipCode: normalizedZip, status: "waiting" },
147→      });
148→    } catch {
149→      waitlistCount = 0;
150→    }
151→
152→    return new Response(
153→      JSON.stringify({
154→        allowed: false,
155→        message: errorMsg,
156→        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
157→        waitlistCount,
158→      }),
159→      { status: 200, headers: SUCCESS_HEADERS },
160→    );
161→  }
162→
163→  // Fetch the most relevant active DeliveryRule for this zip.
164→  // Priority 1: rules that explicitly list this zip in their zipCodes field.
165→  // Priority 2: rules that match by zone (with no explicit zip list).
166→  // Within each priority tier, order by `priority ASC` (lower = higher priority).
167→  const zipCodeUpper = normalizedZip;
168→  const zipZone = zipRecord.zone ?? null;
169→
170→  // Fetch all active rules for the shop ordered by priority so we can apply
171→  // the matching logic in a single query result.
172→  const activeRules = await db.deliveryRule.findMany({
173→    where: { shop, isActive: true },
174→    orderBy: { priority: "asc" },
175→  });
176→
177→  let matchedRule: (typeof activeRules)[number] | null = null;
178→
179→  // Pass 1: explicit zip match — zipCodes field contains this zip code
180→  for (const rule of activeRules) {
181→    if (rule.zipCodes) {
182→      const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
183→      if (zips.includes(zipCodeUpper)) {
184→        matchedRule = rule;
185→        break;
186→      }
187→    }
188→  }
189→
190→  // Pass 2: zone match — rule's zone matches the zip's zone and no explicit zip list
191→  if (!matchedRule && zipZone) {
192→    for (const rule of activeRules) {
193→      if (
194→        rule.zone === zipZone &&
195→        (!rule.zipCodes || rule.zipCodes.trim() === "")
196→      ) {
197→        matchedRule = rule;
198→        break;
199→      }
200→    }
201→  }
202→
203→  // Allowed
204→  const successMsg =
205→    zipRecord.message ??
206→    widgetConfig?.successMessage ??
207→    "Great news! We deliver to your area.";
208→
209→  return new Response(
210→    JSON.stringify({
211→      allowed: true,
212→      message: successMsg,
213→      eta: widgetConfig?.showEta ? (zipRecord.eta ?? null) : null,
214→      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
215→      codAvailable: widgetConfig?.showCod !== false ? (zipRecord.codAvailable ?? null) : null,
216→      returnPolicy: widgetConfig?.showReturnPolicy !== false ? (zipRecord.returnPolicy ?? null) : null,
217→      showWaitlist: false,
218→      waitlistCount: 0,
219→      cutoffTime: widgetConfig?.showCutoffTime !== false ? (matchedRule?.cutoffTime ?? null) : null,
220→      daysOfWeek: widgetConfig?.showDeliveryDays !== false ? (matchedRule?.daysOfWeek ?? null) : null,
221→    }),
222→    { status: 200, headers: SUCCESS_HEADERS },
223→  );
224→  } catch {
225→    return new Response(
226→      JSON.stringify({ error: "Internal server error" }),
227→      { status: 500, headers: CORS_HEADERS },
228→    );
229→  }
230→}
231→
232→// Handle GET requests: ?shop=...&zip=...
233→export const loader = async ({ request }: LoaderFunctionArgs) => {
234→  const url = new URL(request.url);
235→
236→  // Handle CORS preflight
237→  if (request.method === "OPTIONS") {
238→    return new Response(null, { status: 204, headers: CORS_HEADERS });
239→  }
240→
241→  const shop = url.searchParams.get("shop");
242→  const zip = url.searchParams.get("zip");
243→  return handleZipCheck(shop, zip);
244→};
245→
246→// Handle POST requests with JSON body: { shop, zip }
247→export const action = async ({ request }: ActionFunctionArgs) => {
248→  let shop: string | null = null;
249→  let zip: string | null = null;
250→
251→  try {
252→    const body = await request.json();
253→    shop = body?.shop ?? null;
254→    zip = body?.zip ?? null;
255→  } catch {
256→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
257→      status: 400,
258→      headers: CORS_HEADERS,
259→    });
260→  }
261→
262→  return handleZipCheck(shop, zip);
263→};
