378→export default function PricingPage() {
379→  const { subscription } = useLoaderData<typeof loader>();
380→  const fetcher = useFetcher<typeof action>();
381→  const navigate = useNavigate();
382→  const shopify = useAppBridge();
383→
384→  const [isAnnual, setIsAnnual] = useState(
385→    subscription.billingInterval === "annual",
386→  );
387→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
388→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
389→
390→  const data = fetcher.data;
391→  const isFetching = fetcher.state !== "idle";
392→
393→  // Toast for success, Banner for errors (errors must not auto-dismiss)
394→  useEffect(() => {
395→    if (!isFetching) setLoadingPlan(null);
396→    if (data && "message" in data && data.message) {
397→      shopify.toast.show(data.message as string);
398→    }
399→  }, [data, isFetching, shopify]);
400→
401→  const actionError =
402→    data && "error" in data && data.error ? (data.error as string) : null;
403→
404→  const handleSubscribe = useCallback(
405→    (planName: string) => {
406→      setLoadingPlan(planName);
407→      const fd = new FormData();
408→      fd.set("intent", "subscribe");
409→      fd.set("plan", planName);
410→      fetcher.submit(fd, { method: "POST" });
411→    },
412→    [fetcher],
413→  );
414→
415→  const handleConfirmCancel = useCallback(() => {
416→    setCancelModalOpen(false);
417→    setLoadingPlan("cancel");
418→    const fd = new FormData();
419→    fd.set("intent", "cancel");
420→    fetcher.submit(fd, { method: "POST" });
421→  }, [fetcher]);
422→
423→  const currentTier = subscription.planTier;
424→  const currentPlanName =
425→    PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ?? "Free";
426→
427→  // Suggest next tier for upgrade banner
428→  const nextTier =
429→    currentTier === "free"
430→      ? "starter"
431→      : currentTier === "starter"
432→        ? "pro"
433→        : null;
434→
435→  return (
436→    <Page
437→      title="Pricing"
438→      subtitle="Choose the plan that's right for your store"
439→      backAction={{ onAction: () => navigate("/app") }}
440→    >
441→      <Box paddingBlockEnd="1600">
442→      <Layout>
443→        {actionError && (
444→          <Layout.Section>
445→            <Banner tone="critical" title="Billing error">
446→              <Text as="p" variant="bodyMd">{actionError}</Text>
447→            </Banner>
448→          </Layout.Section>
449→        )}
450→        <Layout.Section>
451→          <BlockStack gap="600">
452→
453→            {/* Current plan status */}
454→            {nextTier ? (
455→              <Banner
456→                tone="info"
457→                title={`You're on the ${currentPlanName} plan`}
458→                action={{
459→                  content: `Upgrade to ${PLANS_DATA[nextTier].name}`,
460→                  onAction: () => {
461→                    const plan = isAnnual
462→                      ? PLANS_DATA[nextTier].shopifyPlanAnnual
463→                      : PLANS_DATA[nextTier].shopifyPlanMonthly;
464→                    if (plan) handleSubscribe(plan);
465→                  },
466→                }}
467→              >
468→                <Text as="p" variant="bodyMd">
469→                  {currentTier === "free"
470→                    ? "You have up to 20 allowed zip codes and basic widget access. Upgrade to unlock more features."
471→                    : "Upgrade to Pro for unlimited zip codes, blocked areas, full waitlist, and more."}
472→                </Text>
473→              </Banner>
474→            ) : (
475→              <Banner tone="success" title={`You're on the ${currentPlanName} plan`}>
476→                <InlineStack gap="200" blockAlign="center">
477→                  <Badge tone="success">Active</Badge>
478→                  <Text as="p" variant="bodyMd">
479→                    {currentTier === "ultimate"
480→                      ? "You have full access to all features including VIP support and API access."
481→                      : "You have unlimited zip codes, blocked areas, delivery rules, and more."}
482→                  </Text>
483→                </InlineStack>
484→              </Banner>
485→            )}
486→
487→            {/* Action feedback banners */}
488→            {data && "error" in data && data.error && (
489→              <Banner tone="critical">{String(data.error)}</Banner>
490→            )}
491→            {data && "success" in data && data.success && (
492→              <Banner tone="success">
493→                {data && "message" in data
494→                  ? String(data.message)
495→                  : "Plan updated successfully."}
496→              </Banner>
497→            )}
498→
499→            {/* Billing toggle */}
500→            <BlockStack gap="200" inlineAlign="center">
501→              <ButtonGroup variant="segmented">
502→                <Button
503→                  pressed={!isAnnual}
504→                  onClick={() => setIsAnnual(false)}
505→                >
506→                  Monthly
507→                </Button>
508→                <Button
509→                  pressed={isAnnual}
510→                  onClick={() => setIsAnnual(true)}
511→                >
512→                  Annual · Save up to 38%
513→                </Button>
514→              </ButtonGroup>
515→              {isAnnual && (
516→                <Badge tone="success">You save up to 38% per year</Badge>
517→              )}
518→            </BlockStack>
519→
520→            {/* Plan cards — 4 columns */}
521→            <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
522→              {(
523→                Object.values(
524→                  PLANS_DATA,
525→                ) as (typeof PLANS_DATA)[keyof typeof PLANS_DATA][]
526→              ).map((plan) => (
527→                <PlanCard
528→                  key={plan.id}
529→                  plan={plan}
530→                  isAnnual={isAnnual}
531→                  currentTier={currentTier}
532→                  onSubscribe={handleSubscribe}
533→                  onRequestCancel={() => setCancelModalOpen(true)}
534→                  loadingPlan={loadingPlan}
535→                />
536→              ))}
537→            </InlineGrid>
538→
539→            {/* Trial footnote */}
540→            {(currentTier === "free" || currentTier === "starter") && (
541→              <Text
542→                as="p"
543→                variant="bodySm"
544→                tone="subdued"
545→                alignment="center"
546→              >
547→                All paid plans include a 7-day free trial. No credit card
548→                charged until the trial ends.
549→              </Text>
550→            )}
551→
552→            {/* Set plan directly (for custom app testing) */}
553→            <Banner tone="info" title="Set Plan Manually">
554→              <BlockStack gap="300">
555→                <Text as="p" variant="bodySm">
556→                  Select a plan to activate it directly:
557→                </Text>
558→                <InlineStack gap="200">
559→                  {(["free", "starter", "pro", "ultimate"] as const).map((tier) => (
560→                    <Button
561→                      key={tier}
562→                      size="slim"
563→                      variant={currentTier === tier ? "primary" : "secondary"}
564→                      disabled={currentTier === tier}
565→                      onClick={() => {
566→                        const fd = new FormData();
567→                        fd.set("intent", "test-set-plan");
568→                        fd.set("tier", tier);
569→                        fetcher.submit(fd, { method: "POST" });
570→                      }}
571→                    >
572→                      {tier.charAt(0).toUpperCase() + tier.slice(1)}
573→                    </Button>
574→                  ))}
575→                </InlineStack>
576→              </BlockStack>
577→            </Banner>
578→
579→          </BlockStack>
580→        </Layout.Section>
581→      </Layout>
582→      </Box>
583→
584→      {/* Downgrade confirmation modal */}
585→      <Modal
586→        open={cancelModalOpen}
587→        onClose={() => setCancelModalOpen(false)}
588→        title="Downgrade to Free plan?"
589→        primaryAction={{
590→          content: "Yes, downgrade",
591→          destructive: true,
592→          onAction: handleConfirmCancel,
593→          loading: loadingPlan === "cancel",
594→        }}
595→        secondaryActions={[
596→          {
597→            content: "Keep current plan",
598→            onAction: () => setCancelModalOpen(false),
599→          },
600→        ]}
601→      >
602→        <Modal.Section>
603→          <BlockStack gap="400">
604→            <Text as="p" variant="bodyMd">
605→              Downgrading to Free will immediately remove access to:
606→            </Text>
607→            <BlockStack gap="200">
608→              {[
609→                "Unlimited zip codes — limited to 20",
610→                "Blocked zip codes",
611→                "Delivery rules, zones & ETAs",
612→                "Bulk CSV import & export",
613→                "Customer waitlist",
614→                "Widget customization (colors, position)",
615→                "Cart & checkout blocking",
616→              ].map((item) => (
617→                <InlineStack key={item} gap="200" blockAlign="start" wrap={false}>
618→                  <Text as="span" variant="bodyMd" tone="subdued">·</Text>
619→                  <Text as="p" variant="bodyMd">{item}</Text>
620→                </InlineStack>
621→              ))}
622→            </BlockStack>
623→            <Banner tone="warning">
624→              <Text as="p" variant="bodyMd">
625→                Zip codes over the 20-entry limit will remain saved but become
626→                inactive until you upgrade again.
627→              </Text>
628→            </Banner>
629→          </BlockStack>
630→        </Modal.Section>
631→      </Modal>
632→    </Page>
633→  );
634→}
